INSERT INTO public.fx_rules (code, kind, default_mode, title_ar, title_en) VALUES ('FX09', 'validation', 'log', 'تغيّرت عملة الحساب بعد وجود سطر عليه', 'account currency changed after its first line') ON CONFLICT DO NOTHING;
INSERT INTO public.fx_rules (code, kind, default_mode, title_ar, title_en) VALUES ('FX10', 'action', 'log', 'قيد أجنبي غير متوازن ضمن السماحية', 'foreign entry unbalanced by ≤ tolerance') ON CONFLICT DO NOTHING;
INSERT INTO public.fx_rules (code, kind, default_mode, title_ar, title_en) VALUES ('FX11', 'action', 'log', 'رصيد الحساب بعملته صفر بينما الرصيد المحلي ليس صفراً', 'foreign account ledger AC = 0 while ledger local <> 0') ON CONFLICT DO NOTHING;
INSERT INTO public.fx_rules (code, kind, default_mode, title_ar, title_en) VALUES ('FX12', 'validation', 'log', 'سطر بعملة محلية يحمل مبلغاً أجنبياً أو سعراً غير متوقَّعين', 'base-currency line with a non-zero fc <> local, or rate <> 1') ON CONFLICT DO NOTHING;
INSERT INTO public.fx_rules (code, kind, default_mode, title_ar, title_en) VALUES ('FX13', 'validation', 'log', 'قيمة عمود عملة حساب من العميل خارج السياق الموثوق', 'client-supplied AC-column value outside the trusted context') ON CONFLICT DO NOTHING;
INSERT INTO public.fx_rules (code, kind, default_mode, title_ar, title_en) VALUES ('FX14', 'action', 'log', 'قيمة مكافئ العرض (rc) من العميل خارج السياق الموثوق أو علم كاتب الاستيراد', 'client-supplied reporting-equivalent (rc) value outside the trusted context or the import writer flag') ON CONFLICT DO NOTHING;
INSERT INTO public.fx_rules (code, kind, default_mode, title_ar, title_en) VALUES ('FX15', 'action', 'log', 'الرصيد المخزَّن يختلف عن دفتر الأستاذ', 'stored balance differs from the D12 ledger') ON CONFLICT DO NOTHING;
INSERT INTO public.fx_rules (code, kind, default_mode, title_ar, title_en) VALUES ('FX16', 'action', 'log', 'تعذّر تحديد الدفعة المقدّمة بلا لبس — رُحِّلت الفاتورة بسعرها دون استهلاك الدفعة (B11)', 'Advance position ambiguous — invoice posted at its own rate, advance not consumed (B11)') ON CONFLICT DO NOTHING;
